parameters.jsCode:
// Le nœud 'Ouvrir le run' ne s'exécute qu'une fois (executeOnce) et ne renvoie
// donc qu'un item. On récupère la liste complète des domaines pour alimenter
// la boucle.
return $('Préparer le run').all();

// ── Extraction du texte utile ─────────────────────────────────
//
// Un site d'agence, c'est 200 à 400 ko de HTML dont 2 % de texte. On envoie à
// Claude uniquement ce qui porte du sens : sans ce nettoyage, on paierait
// 50 fois le prix pour un résultat moins bon (le modèle se noie dans le CSS).
//
// On construit ici la requête HTTP complète, schéma JSON compris : le nœud
// suivant ne fait que l'envoyer. Ça évite le cauchemar d'échappement des
// expressions imbriquées et garde le prompt lisible et versionnable.

const config  = $('Configuration').first().json;
const source  = $('Boucle par domaine').item.json;
const html    = String($json.data ?? $json.body ?? '');

// Les entités doivent être décodées partout, titre et meta compris. Sans ça
// le modèle lit « C&#x27;est quoi un agent IA » et peut recopier la séquence
// telle quelle dans la ligne de personnalisation envoyée au prospect.
function decoderEntites(s) {
  return s
    .replace(/&nbsp;/g, ' ')
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
    .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(Number(d)))
    .replace(/&amp;/g, '&'); // en dernier, sinon on décode deux fois
}

function extraireTexte(html) {
  return decoderEntites(
    html
      .replace(/<script[\s\S]*?<\/script>/gi, ' ')
      .replace(/<style[\s\S]*?<\/style>/gi, ' ')
      .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
      .replace(/<svg[\s\S]*?<\/svg>/gi, ' ')
      .replace(/<!--[\s\S]*?-->/g, ' ')
      .replace(/<[^>]+>/g, ' ')
  )
    .replace(/\s+/g, ' ')
    .trim();
}

const titre       = decoderEntites(html.match(/<title[^>]*>([\s\S]*?)<\/title>/i)?.[1] ?? '').trim();
const description = decoderEntites(html.match(/<meta[^>]+name=["']description["'][^>]+content=["']([^"']*)/i)?.[1] ?? '').trim();
const texte       = extraireTexte(html).slice(0, 6000);

// Garde-fou : une page vide (JS-only, mur anti-bot, 200 sur une page blanche)
// ne doit pas partir à l'analyse — on facturerait un appel pour rien et le
// modèle inventerait une entreprise à partir de trois mots.
if (texte.length < 200) {
  throw new Error(`Contenu exploitable insuffisant (${texte.length} caractères) — page probablement rendue en JavaScript ou protégée.`);
}

const schema = {
  type: 'object',
  properties: {
    entreprise:     { type: 'string' },
    ville:          { type: 'string' },
    resume:         { type: 'string' },
    signaux:        { type: 'array', items: { type: 'string' } },
    score:          { type: 'integer' },
    score_pourquoi: { type: 'string' },
    ligne_perso:    { type: 'string' },
  },
  required: ['entreprise', 'ville', 'resume', 'signaux', 'score', 'score_pourquoi', 'ligne_perso'],
  additionalProperties: false,
};

const system = `Tu qualifies des agences pour une campagne de sous-traitance B2B. On vend de la capacité de livraison technique à des agences en surcharge — pas une prestation à des clients finaux.

${config.icp}

RÈGLES DE NOTATION (0 à 100)
- 80-100 : correspond à la cible idéale sur tous les points, avec des signaux de charge visibles.
- 60-79  : agence pertinente, mais un critère manque ou reste incertain.
- 30-59  : activité voisine, sans automatisation ni IA au cœur de l'offre.
- 0-29   : hors cible.

RÈGLES DE RÉDACTION DE ligne_perso
- Une à deux phrases, vouvoiement, écrites pour ouvrir un email à froid.
- Elles doivent citer un élément CONCRET et VÉRIFIABLE lu sur le site : une offre nommée, un secteur servi, un outil mentionné, un parti pris affiché.
- Interdit : la flatterie ("j'adore votre travail"), les généralités applicables à n'importe quelle agence, et toute invention. Si le site ne dit rien de précis, écris une phrase neutre et baisse le score.
- Ponctuation : jamais de tiret cadratin ni de flèche. Ce sont des signatures d'écriture automatique, immédiatement reconnues par des fondateurs techniques. Utilise les deux-points, la virgule, le point ou la parenthèse.

RÈGLE ABSOLUE : tu ne décris que ce qui est présent dans le texte fourni. Aucune donnée venue d'ailleurs, aucune supposition. Si l'information manque, mets une chaîne vide.`;

const contenu = `Domaine : ${source.domaine}\nTitre de la page : ${titre}\nMeta description : ${description}\n\nTexte du site :\n${texte}`;

return [{
  json: {
    run_id:  source.run_id,
    domaine: source.domaine,
    demarre_a: Date.now(),
    corps_requete: {
      model: config.modele,
      max_tokens: 1024,
      system,
      // Sortie structurée : le schéma est appliqué côté API, donc le JSON reçu
      // est valide par construction. Pas de parsing défensif, pas de retry
      // sur JSON malformé — toute une classe de bugs disparaît.
      output_config: { format: { type: 'json_schema', schema } },
      messages: [{ role: 'user', content: contenu }],
    },
  },
}];

// ── Validation ────────────────────────────────────────────────
//
// La sortie structurée garantit la FORME, pas le BON SENS. On vérifie ici ce
// que le schéma ne peut pas vérifier : bornes du score, longueurs plausibles,
// absence de champs vides sur les clés qui pilotent la suite.

const amont  = $('Extraire le texte').item.json;
const source = $('Boucle par domaine').item.json;

const brut = $json.content?.[0]?.text;
if (!brut) {
  throw new Error(`Réponse sans bloc texte exploitable (stop_reason : ${$json.stop_reason ?? 'inconnu'})`);
}

let a;
try {
  a = JSON.parse(brut);
} catch (e) {
  throw new Error(`JSON illisible malgré la sortie structurée : ${String(brut).slice(0, 200)}`);
}

const score = Number(a.score);
if (!Number.isInteger(score) || score < 0 || score > 100) {
  throw new Error(`Score hors bornes : ${a.score}`);
}
if (!a.entreprise || String(a.entreprise).trim().length < 2) {
  throw new Error("Nom d'entreprise absent — le site n'a probablement pas été compris.");
}
if (String(a.ligne_perso ?? '').length > 600) {
  throw new Error('Ligne de personnalisation anormalement longue — sortie suspecte.');
}

const usage = $json.usage ?? {};
const tokensIn  = usage.input_tokens  ?? 0;
const tokensOut = usage.output_tokens ?? 0;

// Tarifs Claude Haiku 4.5 : 1 $ / MTok en entrée, 5 $ / MTok en sortie.
const coutUsd = (tokensIn / 1e6) * 1 + (tokensOut / 1e6) * 5;

// Le tiret cadratin et la flèche sont des signatures d'écriture automatique,
// reconnues au premier coup d'œil par des fondateurs techniques qui utilisent
// ces outils tous les jours. Le prompt les interdit ; on nettoie quand même,
// parce qu'une consigne de prompt est une préférence et pas une garantie.
function assainirPonctuation(s) {
  return s
    .replace(/\s*[—–]\s*/g, ', ')
    .replace(/\s*→\s*/g, ' vers ')
    .replace(/\s{2,}/g, ' ')
    .replace(/,\s*,/g, ',')
    .trim();
}

const lignePerso = assainirPonctuation(String(a.ligne_perso ?? '').trim());

// Le corps complet, pas seulement l'accroche : le script d'envoi expédie le
// champ « Email (corps) » tel quel. N'y mettre que la ligne personnalisée
// enverrait un email d'une seule phrase.
// Les sauts de ligne sont des <br> (convention de la base Notion existante).
// Le prénom reste absent tant que le contact n'est pas trouvé : ce pipeline
// qualifie des entreprises, il n'invente jamais une adresse ni une identité.
const emailCorps = [
  'Bonjour,',
  '',
  lignePerso,
  '',
  "Je construis des automatisations et des agents IA en freelance : n8n, Make, API Claude et OpenAI, Next.js/Supabase. Je m'adresse aux agences plutôt qu'aux clients finaux : je cherche à livrer pour vous, pas à démarcher vos comptes.",
  '',
  "Deux choses que j'ai mises en production, testables en trente secondes :",
  '- t.me/NoriaxDevisBot : un bot qui transforme un message vocal en devis PDF',
  '- noriax.fr : chatbot Claude avec son dashboard de suivi',
  '',
  "Est-ce qu'il vous arrive de sous-traiter du build ?",
  '',
  'Grégoire Long',
  'noriax.fr/sous-traitance',
].join('<br>');

return [{
  json: {
    run_id:  source.run_id,
    domaine: source.domaine,
    site:    source.url,
    entreprise:     String(a.entreprise).trim(),
    ville:          String(a.ville ?? '').trim(),
    resume:         String(a.resume ?? '').trim(),
    signaux:        Array.isArray(a.signaux) ? a.signaux : [],
    score,
    score_pourquoi: String(a.score_pourquoi ?? '').trim(),
    ligne_perso:    lignePerso,
    email_corps:    emailCorps,
    tokens_in:  tokensIn,
    tokens_out: tokensOut,
    cout_usd:   Number(coutUsd.toFixed(6)),
    duree_ms:   Date.now() - amont.demarre_a,
  },
}];

